    "ce": "# Formulas that need a package — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 FormulasThatNeedAPackage.py FormulasThatNeedAPackage\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 684 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass FormulasThatNeedAPackage(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n        template = TexTemplate()\n        template.add_to_preamble(r\"\\usepackage{cancel}\")\n        template_2 = TexTemplate()\n        template_2.add_to_preamble(r\"\\usepackage{physics}\")\n        template_3 = TexTemplate()\n        template_3.add_to_preamble(r\"\\usepackage{bm}\")\n\n        # cancelled: \\frac{\\cancel{x}\\,y}{\\cancel{x}\\,z} = \\frac{y}{z}\n        cancelled = MathTex(r\"\\frac{\\cancel{x}\\,y}{\\cancel{x}\\,z} = \\frac{y}{z}\", font_size=72, tex_template=template)\n        cancelled_g = _glyphs(cancelled, [\n            (-0.6131, 0.2974, 0.2034, 0.1892), (-0.6099, 0.2974, 0.4525, 0.4052), (-0.2011, 0.257, 0.1987, 0.2705), (-0.6079, -0.2974, 0.2034, 0.1892),\n            (-0.6047, -0.2974, 0.4525, 0.4052), (-0.1989, -0.2974, 0.1809, 0.1892), (-0.4727, 0.0036, 0.8199, 0.0251), (0.2659, 0.0036, 0.2782, 0.0977),\n            (0.7444, 0.2311, 0.1987, 0.2705), (0.7465, -0.2974, 0.1809, 0.1892), (0.7386, 0.0036, 0.2882, 0.0251),\n        ])\n\n        # derivative: \\dv{f}{x} = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h}\n        derivative = MathTex(r\"\\dv{f}{x} = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h}\", font_size=72, tex_template=template_2)\n        derivative_g = _glyphs(derivative, [\n            (-2.4956, 0.295, 0.2323, 0.3272), (-2.2295, 0.2524, 0.2295, 0.4219), (-2.5007, -0.3364, 0.2323, 0.3272), (-2.2457, -0.395, 0.2258, 0.21),\n            (-2.3711, -0.061, 0.6157, 0.0278), (-1.6985, -0.061, 0.3088, 0.1085), (-1.3041, -0.0158, 0.1099, 0.3221), (-1.1771, -0.0218, 0.1062, 0.3102),\n            (-0.9177, -0.0743, 0.3681, 0.2052), (-1.2906, -0.3698, 0.1662, 0.2311), (-1.0367, -0.3998, 0.2911, 0.1711), (-0.7911, -0.3762, 0.138, 0.2255),\n            (-0.3894, 0.2682, 0.2295, 0.4219), (-0.1756, 0.2682, 0.1108, 0.4636), (0.0348, 0.2522, 0.2258, 0.21), (0.4543, 0.2684, 0.3088, 0.3083),\n            (0.8774, 0.3106, 0.235, 0.3268), (1.0856, 0.2682, 0.1108, 0.4636), (1.4684, 0.2682, 0.2828, 0.0185), (1.892, 0.2682, 0.2295, 0.4219),\n            (2.1057, 0.2682, 0.1108, 0.4636), (2.3162, 0.2522, 0.2258, 0.21), (2.5332, 0.2682, 0.1108, 0.4636), (1.0577, -0.3366, 0.235, 0.3268),\n            (1.0515, -0.061, 3.2549, 0.0278),\n        ])\n\n        # vectors: \\bm{F} = m\\,\\bm{a}\n        vectors = MathTex(r\"\\bm{F} = m\\,\\bm{a}\", font_size=72, tex_template=template_3)\n        vectors_g = _glyphs(vectors, [\n            (-2.1603, 0.008, 1.1085, 0.9841), (-0.6411, -0.1223, 0.9638, 0.3386), (0.9592, -0.1717, 1.2098, 0.6565), (2.3029, -0.1638, 0.8234, 0.6676),\n        ])\n\n        # 0 s – 1.4 s: cancelled write\n        self.play(Write(VGroup(*cancelled_g[:])), run_time=1.4)\n        # 1.4 s – 3.2 s\n        self.wait(1.8)\n        # 3.2 s – 3.8 s: cancelled fade_out\n        self.play(FadeOut(cancelled), run_time=0.6)\n        # 3.8 s – 5.2 s: derivative write\n        self.play(Write(VGroup(*derivative_g[:])), run_time=1.4)\n        # 5.2 s – 7 s\n        self.wait(1.8)\n        # 7 s – 7.6 s: derivative fade_out\n        self.play(FadeOut(derivative), run_time=0.6)\n        # 7.6 s – 9 s: vectors write\n        self.play(Write(VGroup(*vectors_g[:])), run_time=1.4)\n        # 9 s – 10.8 s\n        self.wait(1.8)\n        # 10.8 s – 11.4 s: vectors fade_out\n        self.play(FadeOut(vectors), run_time=0.6)\n",
